const productLinks=window.portfolioData.links;
let lang=localStorage.getItem("fardar-lang")||((navigator.language||"fa").toLowerCase().startsWith("zh")?"zh":(navigator.language||"fa").toLowerCase().startsWith("ar")?"ar":(navigator.language||"fa").toLowerCase().startsWith("en")?"en":"fa");
function render(){const c=content[lang];document.documentElement.lang=lang==="zh"?"zh-CN":lang;document.documentElement.dir=c.dir;document.title=lang==="fa"?"حمیدرضا فاردار — مدیر تحول دیجیتال":"Hamidreza Fardar — Digital Transformation Leader";document.querySelectorAll("[data-t]").forEach(el=>{const v=c[el.dataset.t];if(v!==undefined)el.innerHTML=v});document.querySelectorAll("[data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));document.getElementById("pain-grid").innerHTML=c.pains.map((x,i)=>`<article class="pain-item smart-pain"><span class="pain-icon">${window.portfolioIcon(["layers","chart","currency","sparkles"][i],i)}</span><strong>${x}</strong><i aria-hidden="true"></i></article>`).join("");document.getElementById("solution-grid").innerHTML=c.solutions.map((x,i)=>`<article class="solution-card"><span class="solution-icon animated-icon">${window.portfolioIcon(["flow","chart","currency","layers"][i],i)}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join("");document.getElementById("product-grid").innerHTML=c.products.map((x,i)=>{const external=/^https?:/.test(productLinks[i]);return `<article class="product-card product-card-${i%4}"><div class="product-visual">${window.portfolioPreview(i)}<span class="product-icon">${window.portfolioIcon(window.portfolioData.icons[i],i)}</span><small>0${i+1} / SELECTED WORK</small></div><span class="product-tag">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p><a class="text-link" href="${productLinks[i]}"${external?' target="_blank" rel="noreferrer"':''}><span>${x[3]}</span><b>↗</b></a></article>`}).join("");document.getElementById("compare-list").innerHTML=c.compare.map(x=>`<div class="compare-row"><span>${x[0]}</span><b class="change-label">${c.mustBecome}</b><span>${x[1]}</span></div>`).join("");document.getElementById("process-grid").innerHTML=c.process.map((x,i)=>`<article class="process-card"><span class="process-node">${window.portfolioIcon(["sparkles","layers","flow","chart"][i],i)}</span><small>0${i+1}</small><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join("");document.getElementById("timeline").innerHTML=c.timeline.map((x,i)=>`<article class="timeline-item"><span class="timeline-icon">${window.portfolioIcon(["factory","flow","chart","layers","users","bank","sparkles"][i%7],i)}</span><time>${x[0]}</time><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join("");document.getElementById("learning-grid").innerHTML=c.learning.map((x,i)=>`<article class="learning-card"><div class="learning-orbit"><span class="learning-icon">${window.portfolioIcon(["chart","layers","bank","sparkles"][i],i)}</span><b>0${i+1}</b></div><small>${x[0]}</small><h3>${x[1]}</h3><p>${x[2]}</p><div class="knowledge-line"><i></i><i></i><i></i><i></i></div></article>`).join("");const active=document.querySelector(".sim-node.active");setSimStep(active?Number(active.dataset.step):0)}
document.querySelectorAll("[data-lang]").forEach(btn=>btn.addEventListener("click",()=>{lang=btn.dataset.lang;localStorage.setItem("fardar-lang",lang);render()}));
document.querySelector(".menu-button").addEventListener("click",e=>{const nav=document.querySelector(".mobile-nav");const open=nav.classList.toggle("open");e.currentTarget.setAttribute("aria-expanded",String(open))});document.querySelectorAll(".mobile-nav a").forEach(a=>a.addEventListener("click",()=>{document.querySelector(".mobile-nav").classList.remove("open");document.querySelector(".menu-button").setAttribute("aria-expanded","false")}));
document.getElementById("contact-form").addEventListener("submit",e=>{e.preventDefault();const d=new FormData(e.currentTarget);const subject=encodeURIComponent(`Consultation request — ${d.get("company")||d.get("name")}`);const body=encodeURIComponent(`Name: ${d.get("name")}\nCompany: ${d.get("company")}\nContact: ${d.get("contact")}\n\nChallenge:\n${d.get("problem")}`);location.href=`mailto:projects@fardar.ir?subject=${subject}&body=${body}`});
function setSimStep(step){document.querySelectorAll(".sim-node").forEach((node,i)=>node.classList.toggle("active",i===step));document.getElementById("sim-value").textContent=content[lang].simValues[step];document.getElementById("sim-meter-fill").style.width=`${25*(step+1)}%`}
document.querySelectorAll(".sim-node").forEach(node=>node.addEventListener("click",()=>setSimStep(Number(node.dataset.step))));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle("visible",e.isIntersecting)),{threshold:.08});document.querySelectorAll(".reveal").forEach(el=>observer.observe(el));render();
